import { Battle, UNITS, LEVELS, WORLD, population } from './engine.js';
import { Renderer, icons, icon, portrait } from './art-v2.js';
import { VERSION, REGIONS, SKINS, ITEMS, GOALS, missionText } from './content.js';
import { SAVE_KEY, freshProgress, migrateProgress, canPlay, purchaseSkin, equipSkin, purchaseItem, recordVictory } from './progress.js';

const $ = id => document.getElementById(id);
const unitTypes = Object.keys(UNITS), fmt = n => Math.floor(n).toLocaleString('zh-CN');
const clock = n => `${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
let save=freshProgress(), saveAvailable=true, migrated=false;
try { const raw=JSON.parse(localStorage.getItem(SAVE_KEY)); const parsed=migrateProgress(raw); save=parsed.save; migrated=parsed.migrated; if(migrated&&!localStorage.getItem('ember-kingdom-backup-v1'))localStorage.setItem('ember-kingdom-backup-v1',JSON.stringify(raw)); } catch { saveAvailable=false; }
let wardrobeUnit='sword', wardrobeTab='skins', campaignChapter=null;
let battle;
try { battle = Battle.restore(save.checkpoint); } catch { battle = null; }
if (!battle) battle = new Battle({level:save.selectedLevel,difficulty:save.difficulty,upgrades:save.upgrades,loadout:save.loadout});
const renderer = new Renderer($('battlefield'), $('minimap'));
renderer.reduced = save.reduced;
let modalOpen = false, wasPlaying = false, modalReturnFocus = null, speed = 1, messageTimer, toastTimer, uiTime = 0, saveTime = 0, lastTime = performance.now(), resultHandled = false;
let touchControls;
class Sound {
  constructor(){this.enabled=save.sound;this.ctx=null;this.lastHit=0;}
  unlock(){if(!this.enabled)return;try{this.ctx ||= new(window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}catch{}}
  tone(freq=440,duration=.08,type='sine',volume=.04,delay=0){if(!this.enabled)return;this.unlock();if(!this.ctx)return;const ctx=this.ctx,o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.6),t+duration);g.gain.setValueAtTime(volume,t);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+duration+.02);}
  play(type){if(type==='attack'){if(performance.now()-this.lastHit<180)return;this.lastHit=performance.now();this.tone(130,.055,'triangle',.026);}else if(type==='train')this.tone(480,.07,'triangle');else if(type==='trained'){this.tone(480,.1);this.tone(640,.15,'sine',.04,.08);}else if(type==='wave'){this.tone(140,.3,'sawtooth',.016);this.tone(110,.5,'triangle',.05,.2);}else if(type==='skill'){[440,554,660].forEach((f,i)=>this.tone(f,.4,'sine',.03,i*.08));}else if(type==='win'){[392,494,587,784].forEach((f,i)=>this.tone(f,.5,'triangle',.04,i*.17));}else this.tone(280,.09,'triangle',.025);}
}
const sound = new Sound();
function persist(checkpoint = true){if(checkpoint)save.checkpoint=['ready','playing','paused'].includes(battle.status)?battle.snapshot():null;try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));saveAvailable=true;}catch{saveAvailable=false;document.querySelector('footer>span:last-child').textContent='存储不可用 · 请勿关闭当前页面';}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2900);}
function announce(text){$('battle-message').textContent=text;$('battle-message').classList.add('visible');clearTimeout(messageTimer);messageTimer=setTimeout(()=>$('battle-message').classList.remove('visible'),3600);}
function renderStatic(){
  $('unit-grid').innerHTML=unitTypes.map((key,i)=>{const d=UNITS[key];return `<button class="unit-card" data-unit="${key}" title="${d.name} · ${d.cost} 黄金 · ${d.pop} 人口\n${d.desc}" aria-label="训练${d.name}，${d.cost}黄金，快捷键${i+1}"><kbd class="unit-key">${i+1}</kbd><span class="unit-role">${d.role}</span><span class="unit-count"></span><div class="unit-portrait">${portrait(key,battle.loadout[key])}</div><div class="unit-meta"><span class="unit-name">${d.name}<small class="skin-label">${SKINS[battle.loadout[key]]?.en||"CLASSIC"}</small></span><span class="unit-price">${icon('coins')}${d.cost}<span class="train-time">${d.train}秒</span></span></div><span class="train-progress"></span></button>`;}).join('');
  renderLevel();renderItems();icons();
}
function renderLevel(){
  const l=LEVELS[battle.level],r=REGIONS[l.chapter];
  document.body.dataset.biome=battle.survival?'night':l.biome;
  $('level-index').textContent=battle.survival?'∞':String(battle.level+1).padStart(2,'0');
  $('level-title').innerHTML=`${battle.survival?'无尽防线':l.title}<span class="title-dot">.</span>`;
  $('level-subtitle').textContent=battle.survival?'坚守每一道防线，直到最后一位战士。':l.subtitle;
  $('battle-caption').textContent=battle.survival?'无尽防线':`${r.name} · ${l.stage}/5`;
  $('weather-caption').textContent=battle.survival?'永夜':r.weather;
  $('difficulty-label').textContent=({easy:'休闲难度',normal:'标准难度',hard:'困难难度'})[battle.difficulty];
  $('objective-level').textContent=battle.level+1;
  $('objective-copy').textContent=battle.survival?'守住雕像，挑战你的波次纪录。':missionText(l);
  $('ready-copy').textContent=battle.survival?'敌军将不断变强，坚守尽可能多的波次。':missionText(l);
  $('campaign-progress').innerHTML=REGIONS.map((r,i)=>`${i?'<span class="progress-line"></span>':''}<button class="progress-node ${i===l.chapter&&!battle.survival?'current':''} ${save.cleared[i*5+4]?'completed':''}" data-chapter="${i}" title="${r.name}" aria-label="查看${r.name}">${save.cleared[i*5+4]?'✓':i+1}</button>`).join('');
}
function renderItems(){
  $('item-grid').innerHTML=Object.entries(ITEMS).map(([id,item])=>`<button class="item-button" data-use-item="${id}" title="${item.name}：${item.desc}"><span class="item-icon" style="--item-color:${item.color}">${icon(item.icon)}</span><span class="item-copy"><b>${item.name}</b><small>${item.short}</small></span><span class="item-stock" id="stock-${id}">${save.inventory[id]||0}</span></button>`).join('');
}
function updateUI(){
  $('gold').textContent=fmt(battle.gold);$('population').textContent=population(battle.units);$('gems').textContent=save.gems;$('timer').textContent=clock(battle.time);
  $('ally-health').style.width=`${Math.max(0,battle.baseHP/battle.baseMax*100)}%`;$('enemy-health').style.width=`${Math.max(0,battle.enemyHP/battle.enemyMax*100)}%`;$('ally-hp').textContent=fmt(battle.baseHP);$('enemy-hp').textContent=battle.survival||['defend','escort'].includes(battle.config.goal)?'∞':fmt(battle.enemyHP);
  $('mission-live').textContent=missionText(battle.config,battle);$('wave-live').textContent=`第 ${battle.wave} 波 · 下波 ${Math.max(0,Math.ceil(battle.nextWave-battle.time))} 秒`;$('item-cd').textContent=battle.itemCooldown>0?`准备 ${Math.ceil(battle.itemCooldown)} 秒`:'共享冷却 8 秒';for(const id of Object.keys(ITEMS)){const el=$('stock-'+id);if(el)el.textContent=save.inventory[id]||0;}
  $('ready-card').classList.toggle('hidden',battle.status!=='ready');$('pause-cover').classList.toggle('hidden',battle.status!=='paused'||modalOpen);
  $('pause-button').innerHTML=icon(battle.status==='paused'?'play':'pause');$('pause-button').setAttribute('aria-label',battle.status==='paused'?'继续战斗':'暂停游戏');
  $('order-status').textContent=battle.selected?'正在直接控制单位':battle.survival?`第 ${battle.wave} 波 · 军团正在${{garrison:'驻守',defend:'防守',attack:'进攻'}[battle.order]}`:`军团正在${{garrison:'驻守',defend:'防守',attack:'进攻'}[battle.order]}`;
  document.querySelectorAll('[data-command]').forEach(el=>{el.classList.toggle('active',el.dataset.command===battle.order);el.setAttribute('aria-pressed',String(el.dataset.command===battle.order));});
  $('queue-indicator').innerHTML=`训练队列 <b>${battle.queue.length} / 5</b>${battle.queue.length?' · 点击管理':''}`;
  document.querySelectorAll('[data-unit]').forEach(el=>{const key=el.dataset.unit,d=UNITS[key],queued=battle.queue.filter(q=>q.type===key).length;el.classList.toggle('unaffordable',battle.gold<d.cost);const c=el.querySelector('.unit-count');c.textContent=queued;c.style.display=queued?'flex':'none';const first=battle.queue[0];el.querySelector('.train-progress').style.width=first?.type===key?`${(1-first.remaining/first.total)*100}%`:'0%';});
  for(const key of ['rage','heal']){const cd=battle[key+'Cooldown'];$(key+'-button').classList.toggle('cooling',cd>0);$(key+'-status').textContent=cd>0?(key==='rage'&&battle.rage>0?`狂怒中 · 剩余 ${Math.ceil(battle.rage)} 秒`:`冷却 ${Math.ceil(cd)} 秒`):(key==='rage'?'伤害 +60% · 12 秒':'全军恢复 45% 生命');$(key+'-button').querySelector('.skill-cooldown').style.width=`${cd/(key==='rage'?55:65)*100}%`;}
  $('sound-button').innerHTML=icon(sound.enabled?'volume':'volume-off');$('sound-button').setAttribute('aria-label',sound.enabled?'关闭音效':'开启音效');
  const selected=battle.units.find(u=>u.id===battle.selected);
  if(selected){$('selected-unit').classList.remove('hidden');$('selected-unit').innerHTML=`<strong>${UNITS[selected.type].name}</strong> <span>· ${fmt(selected.hp)} / ${selected.maxHP}</span><small>A / D 移动 · 空格攻击<br>手动攻击伤害 +35%</small><button data-action="release">交还军团指挥（Esc）</button>`;if(!touchControls&&matchMedia('(pointer:coarse)').matches){touchControls=document.createElement('div');touchControls.className='touch-controls';touchControls.innerHTML='<button data-manual="left" aria-label="向左移动">←</button><button data-manual="right" aria-label="向右移动">→</button><button data-manual="attack" aria-label="攻击">⚔</button>';$('battle-viewport').append(touchControls);touchControls.querySelectorAll('button').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);battle.manual[btn.dataset.manual]=true;});['pointerup','pointercancel','lostpointercapture'].forEach(type=>btn.addEventListener(type,()=>battle.manual[btn.dataset.manual]=false));});}}else{$('selected-unit').classList.add('hidden');if(touchControls){touchControls.remove();touchControls=null;}}
}
function showModal(html){if(!modalOpen){modalReturnFocus=document.activeElement;wasPlaying=battle.status==='playing';if(wasPlaying)battle.status='paused';}modalOpen=true;battle.manual={left:false,right:false,attack:false};$('modal-content').innerHTML=html;$('modal-backdrop').classList.remove('hidden');icons($('modal-backdrop'));document.querySelector('.modal').focus();updateUI();}
function closeModal(resume=true){modalOpen=false;$('modal-backdrop').classList.add('hidden');if(resume&&wasPlaying&&battle.status==='paused')battle.status='playing';wasPlaying=false;if(modalReturnFocus?.isConnected)modalReturnFocus.focus({preventScroll:true});updateUI();}
function modalHeader(kicker,title,intro){return `<div class="modal-eyebrow">${kicker}</div><h2 id="modal-title">${title}</h2><p class="modal-intro">${intro}</p>`;}
function campaign(tab='campaign',chapter=campaignChapter??Math.floor(battle.level/5)){
  campaignChapter=Math.max(0,Math.min(5,chapter));const r=REGIONS[campaignChapter];
  const intro=modalHeader('THE CONQUEST · 30 ENCOUNTERS','王国征途','六片土地，三十场战役。每一面旗帜，都是一次新的选择。');
  const tabs=`<div class="modal-tabs"><button class="modal-tab ${tab==='campaign'?'active':''}" data-campaign-tab="campaign">王国战役 · 30 关</button><button class="modal-tab ${tab==='survival'?'active':''}" data-campaign-tab="survival">无尽防线</button></div>`;
  if(tab==='survival'){showModal(intro+tabs+`<div class="survival-card"><div class="modal-eyebrow">ENDLESS NIGHT</div><h3>最后一面旗帜，绝不倒下。</h3><p>第 28 秒迎来首波敌军，此后每 36 秒来袭。每 3 波解锁更强的敌方兵种。<br>敌方雕像不可摧毁；坚持每 3 波结算 1 水晶，最多 5 个。<br>个人纪录：<strong>${save.bestWave} 波</strong></p><button class="primary-button" data-action="survival">开始坚守 ${icon('arrow-right')}</button></div>`);return;}
  const nodes=[[9,66],[29,34],[50,62],[70,29],[91,55]],levels=LEVELS.slice(campaignChapter*5,campaignChapter*5+5);
  const chapters=REGIONS.map((v,i)=>`<button class="chapter-button ${i===campaignChapter?'active':''}" data-chapter="${i}"><span>${v.symbol}</span><b>${v.name}</b><small>${Object.keys(save.cleared).filter(n=>Math.floor(Number(n)/5)===i).length}/5</small></button>`).join('');
  const map=`<div class="campaign-route" data-region="${r.id}" style="--region:${r.color}"><div class="map-heading"><small>${r.subtitle}</small><b>${r.name}</b></div><svg class="route-path" viewBox="0 0 800 180" preserveAspectRatio="none" aria-hidden="true"><path d="M72 119C120 150 150 30 232 61S340 150 400 112 510 20 560 52 650 150 728 99"/></svg>${levels.map((l,i)=>`<button class="route-node ${canPlay(save,l.chapter*5+i)?'unlocked':'locked'} ${save.cleared[l.chapter*5+i]?'completed':''}" style="left:${nodes[i][0]}%;top:${nodes[i][1]}%" data-select-level="${l.chapter*5+i}" aria-label="${l.title}"><span>${save.cleared[l.chapter*5+i]?'✓':canPlay(save,l.chapter*5+i)?String(l.chapter*5+i+1).padStart(2,'0'):icon('lock')}</span><small>${l.title}</small></button>`).join('')}</div>`;
  const cards=levels.map(l=>{const i=l.chapter*5+l.stage-1,locked=!canPlay(save,i),stars=save.cleared[i]||0;return `<button class="encounter-card ${l.stage===5?'boss-card':''}" data-select-level="${i}"><span class="encounter-number">${String(i+1).padStart(2,'0')}</span><div><b>${l.title}</b><small>${GOALS[l.goal]}${l.stage===5?' · 统领战':''}</small></div><span class="encounter-stars">${locked?icon('lock'):stars?'★'.repeat(stars)+'☆'.repeat(3-stars):`◇ ${l.reward}`}</span>${icon('chevron-right')}</button>`;}).join('');
  showModal(intro+tabs+`<div class="chapter-nav">${chapters}</div>${map}<div class="encounter-grid">${cards}</div><p class="upgrade-note">已征服 ${Object.keys(save.cleared).length}/30 关 · 首次通关获得水晶，重玩通关获得 1 水晶。${migrated?'旧版星级已映射到对应章节终章。':''}</p>`);
}
function levelBrief(level){
  const l=LEVELS[level];if(!l)return;const available=canPlay(save,level),m={normal:'晴朗天气，无额外修正',rich:'丰富矿脉：每趟黄金 +30%',sunset:'注意倒计时，在时限内完成突破',sandstorm:'沙暴：弓手和巫师射程 -20%',snow:'冰雪：所有单位移动速度 -14%',fog:'迷雾：弓手和巫师射程 -20%',embers:'中央熔岩地带每 8 秒喷发，造成 18 伤害',night:'星夜环境，注意混编敌军',boss:'精锐统领将随指定波次加入战斗'};
  showModal(modalHeader(`CHAPTER ${l.chapter+1} · MISSION ${String(level+1).padStart(2,'0')}`,l.title,l.text)+`<div class="mission-brief-goal">${icon(l.goal==='escort'?'cart':l.goal==='defend'?'shield':l.goal==='timed'?'clock':'swords')}<span><small>胜利条件</small><b>${missionText(l)}</b></span></div><div class="brief-columns"><div><h3>战场情报</h3><p>${m[l.modifier]}</p><p>初始黄金 <b>${l.startGold}</b> · 首通奖励 <b>${l.reward} ◇</b></p><p>敌方军团：${l.types.map(t=>UNITS[t].name).join('、')}</p></div><div><h3>敌军波次</h3>${l.waves.map(w=>`<p class="wave-brief"><b>${clock(w.at)}</b><span>${w.units.map(t=>UNITS[t.replace('!','')].name+(t.endsWith('!')?'统领':'')).join(' · ')}</span></p>`).join('')}</div></div><div class="tactic-note">${icon('sparkles')}<p>${l.tip}</p></div><p class="upgrade-note">${available?(battle.time>0?'开始新战斗将替换当前战场，保留已获得的进度、装备与道具。':'战前检查你的皮肤和补给，准备好再出发。'):'完成前一关即可解锁。可返回地图选择已解锁的关卡。'}</p><div class="result-actions"><button class="secondary-button" data-action="campaign">返回地图</button><button class="primary-button" data-new-level="${level}" ${available?'':'disabled'}>${available?'出征':'尚未解锁'} ${icon(available?'arrow-right':'lock')}</button></div>`);
}
function armory(tab=wardrobeTab){
  wardrobeTab=tab;const tabs=`<div class="modal-tabs"><button class="modal-tab ${tab==='skins'?'active':''}" data-armory-tab="skins">装备皮肤</button><button class="modal-tab ${tab==='upgrades'?'active':''}" data-armory-tab="upgrades">永久升级</button><button class="modal-tab ${tab==='supplies'?'active':''}" data-armory-tab="supplies">补给道具</button></div>`;
  const header=modalHeader('YOUR LEGION · YOUR LEGACY','军团兵营','选择战甲，锻造装备，装满你的行囊。每一次准备，都将改变战场。')+`<div class="armory-balance">${icon('gem')}可用水晶 <b>${save.gems}</b><span>通过游戏获得 · 无付费购买</span></div>`+tabs;
  if(tab==='supplies'){showModal(header+`<div class="supply-catalog">${Object.entries(ITEMS).map(([id,d])=>`<article class="supply-card"><span class="large-item-icon" style="color:${d.color}">${icon(d.icon)}</span><div><h3>${d.name}</h3><p>${d.desc}</p><small>已拥有 ${save.inventory[id]||0} 个</small></div><button class="upgrade-button" data-buy-item="${id}" ${save.gems<d.cost||save.inventory[id]>=99?'disabled':''}>${d.cost} ◇ 兑换</button></article>`).join('')}</div><p class="upgrade-note">道具在战场下方行囊中使用，共享 8 秒冷却。条件不满足时不会消耗库存。库存会自动保存。</p>`);return;}
  if(tab==='upgrades'){showModal(header+`<div class="upgrade-list">${[...unitTypes,'statue'].map(type=>{const l=save.upgrades[type]||0;return `<div class="upgrade-card"><div class="mini-portrait">${type==='statue'?icon('shield'):portrait(type,save.loadout[type])}</div><div><b>${type==='statue'?'秩序雕像':UNITS[type].name}</b><p>${type==='miner'?'开采速度与黄金产量提升':type==='statue'?'每级 +400 雕像生命':'每级 +16% 生命与伤害'}</p><span class="upgrade-dots">${[0,1,2].map(i=>`<i class="${i<l?'on':''}"></i>`).join('')}</span></div><button class="upgrade-button" data-upgrade="${type}" ${l>=3||save.gems<l+1?'disabled':''}>${l>=3?'已满级':`${l+1} ◇ 升级`}</button></div>`;}).join('')}</div><p class="upgrade-note">永久升级将在下一场战斗生效。每种升级最多 3 级，依次消耗 1、2、3 水晶。</p>`);return;}
  const unitTabs=`<div class="wardrobe-units">${unitTypes.map(type=>`<button class="${type===wardrobeUnit?'active':''}" data-wardrobe-unit="${type}">${portrait(type,save.loadout[type])}<span>${UNITS[type].name}</span></button>`).join('')}</div>`;
  const skins=Object.entries(SKINS).map(([id,s])=>{const owned=save.ownedSkins.includes(id),equipped=save.loadout[wardrobeUnit]===id;return `<article class="skin-card ${equipped?'equipped':''}" style="--skin:${s.accent}"><div class="skin-preview">${portrait(wardrobeUnit,id)}<span>${s.en}</span>${equipped?'<i>已装备</i>':''}</div><div class="skin-info"><h3>${s.name}</h3><b>${s.perk}</b><p>${s.detail}</p><button class="skin-equip" ${equipped?'disabled':owned?`data-equip-skin="${id}"`:`data-buy-skin="${id}" ${save.gems<s.cost?'disabled':''}`}>${equipped?'当前装备':owned?'为此兵种装备':`${s.cost} ◇ 解锁全军皮肤`}</button></div></article>`;}).join('');
  showModal(header+unitTabs+`<div class="skin-grid">${skins}</div><p class="upgrade-note">一套皮肤解锁后可为六种兵种分别装备。未开战时立即换装；已开战时在下一场生效。皮肤效果可与永久升级同时生效。</p>`);
}
function supplies(){armory('supplies');}
function applyReadyLoadout(){if(battle.status==='ready'){battle.loadout={...save.loadout};for(const u of battle.units)if(!u.team)u.skin=save.loadout[u.type]||'classic';renderStatic();}}
function useItem(id){if((save.inventory[id]||0)<=0){toast('行囊里没有这件道具，可在补给商店兑换');return;}const result=battle.useItem(id);if(!result.ok){toast(result.message);return;}save.inventory[id]--;persist();updateUI();sound.play('skill');announce(`${ITEMS[id].name} · ${ITEMS[id].short}`);}
function codex(){showModal(modalHeader('KNOW YOUR LEGION','战争图鉴','没有无敌的战士，只有相互信任的军团。了解他们，才能带领他们。')+`<div class="codex-grid">${unitTypes.map(type=>{const d=UNITS[type];return `<article class="codex-card"><div class="codex-art">${portrait(type,save.loadout[type])}</div><div><h3>${d.name} <small style="font-size:9px;color:#9aa084;font-weight:400">${d.role}</small></h3><p>${d.desc}</p><div class="codex-stats"><span>♥ ${d.hp}</span><span>⚔ ${d.damage}</span><span>人口 ${d.pop}</span></div></div></article>`;}).join('')}</div><p class="upgrade-note">图鉴展示基础属性；兵工厂升级会增强下一场战斗中的我方单位。</p>`);}
function settings(){showModal(modalHeader('MAKE IT YOURS','游戏设置','调整你的战场体验。准备好后，继续书写传奇。')+`<div class="settings-row"><div><h3>战斗难度</h3><p>影响敌军强度与训练速度，下一场战斗生效</p></div><select id="difficulty-select" aria-label="战斗难度">${Object.entries({easy:'休闲',normal:'标准',hard:'困难'}).map(([v,l])=>`<option value="${v}" ${save.difficulty===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="settings-row"><div><h3>战斗音效</h3><p>训练、交战与技能提示音</p></div><button class="toggle ${sound.enabled?'on':''}" data-action="settings-sound" role="switch" aria-checked="${sound.enabled}" aria-label="战斗音效"></button></div><div class="settings-row"><div><h3>减少动态效果</h3><p>关闭背景和待机摆动，保留战斗反馈</p></div><button class="toggle ${save.reduced?'on':''}" data-action="reduced" role="switch" aria-checked="${save.reduced}" aria-label="减少动态效果"></button></div><div class="settings-row"><div><h3>进度已自动保存</h3><p>${saveAvailable?'战役、升级与当前战斗保存在此浏览器':'此浏览器无法保存，请保持页面开启'}</p></div><span style="color:#8b9b70">${icon('check')}</span></div><div class="settings-actions"><button class="text-button" data-action="restart-confirm">重新开始本关</button><button class="primary-button" data-action="close-modal">返回战场 ${icon('arrow-right')}</button></div>`);}
function help(){showModal(modalHeader('A COMMANDER’S HANDBOOK','战争手册','先让矿镐响起，再让剑锋指向远方。')+`<div class="help-grid"><article class="help-step"><span>01</span><h3>先建立经济</h3><p>点击「开始战斗」，训练矿工。矿工会自动开采并运回黄金。建议先拥有 3–5 名矿工。</p></article><article class="help-step"><span>02</span><h3>组建混编军团</h3><p>点击兵种卡片训练单位。黄金立即扣除，按队列依次出兵。队列最多 5 个，总人口上限 40。</p></article><article class="help-step"><span>03</span><h3>掌握进退时机</h3><p>防守：在基地前集结。进攻：向敌方雕像推进。驻守：全军返回基地并缓慢恢复生命。</p></article><article class="help-step"><span>04</span><h3>扭转战局</h3><p>狂怒提高伤害，治疗恢复全军生命。点击我方战士可亲自控制，手动攻击额外提高 35% 伤害。</p></article></div><div class="help-step"><h3>四种任务，先读目标</h3><p>攻城关摧毁敌方雕像；防守关坚持到计时结束；限时关必须赶在期限前攻城；护送关让矿车抵达右侧终点。矿车等待前方护卫，附近有敌人会停下。守护自己的雕像始终重要。</p><h3>装备与战术行囊</h3><p>在军团兵营兑换七套皮肤，可分别为六个兵种换装。皮肤在准备时立即生效，战斗中换装从下一局开始。六种道具共用 8 秒冷却；成功使用才消耗库存。水晶来自通关，不提供付费购买。</p><p>想和孩子一起制作游戏？打开顶部「亲子工坊」，从纸上规则与 12 个小作品开始。</p></div><div class="keyboard-guide"><kbd>1</kbd>–<kbd>6</kbd> 训练兵种　 <kbd>Z</kbd>驻守　<kbd>X</kbd>防守　<kbd>C</kbd>进攻<br><kbd>Q</kbd>狂怒　<kbd>E</kbd>治疗　<kbd>P</kbd>暂停　<kbd>←</kbd><kbd>→</kbd>移动视野<br><kbd>A</kbd><kbd>D</kbd>控制单位移动　<kbd>空格</kbd>攻击　<kbd>Esc</kbd>退出控制<br>触屏：拖动战场移动视野；选中单位后使用屏幕方向与攻击按钮。<br>点击小地图快速查看战场，点击训练队列可取消训练并全额退款。</div>`);}
function queue(){showModal(modalHeader('TRAINING QUEUE','训练队列','军团正在整装待发。取消训练可返还全部黄金。')+(battle.queue.length?`<div class="queue-list">${battle.queue.map((q,i)=>`<div class="queue-row"><b>${i+1}. ${UNITS[q.type].name}</b><small>${i===0?`剩余 ${q.remaining.toFixed(1)} 秒`:'等待训练'}</small><button data-cancel-training="${i}">取消 · 返还 ${UNITS[q.type].cost}</button></div>`).join('')}</div>`:'<p class="modal-intro">训练队列为空，点击战场下方的兵种卡片招募军队。</p>'));}
function newBattle(level,survival=false){battle=new Battle({level,difficulty:save.difficulty,upgrades:save.upgrades,loadout:save.loadout,survival,seed:Date.now()>>>0});resultHandled=false;campaignChapter=null;save.selectedLevel=level;speed=1;$('speed-button').textContent='1×';renderer.setCamera(0,true);closeModal(false);renderStatic();updateUI();persist();}
function endBattle(win){
  if(resultHandled)return;resultHandled=true;let reward=0;
  if(battle.survival){save.bestWave=Math.max(save.bestWave,battle.wave);reward=Math.min(5,Math.floor(battle.wave/3));save.gems+=reward;}
  else if(win){reward=recordVictory(save,battle).reward;}
  save.checkpoint=null;persist(false);renderLevel();sound.play(win?'win':'wave');
  const victory={destroy:'敌方雕像轰然倒下，你的旗帜在新的土地上升起。',timed:'你在时限内突破了敌军防线。时机与勇气赢得了这一战。',defend:'你守住了整条防线，所有的坚持都有了回响。',escort:'矿车平安抵达终点。军团的补给线已经打通。'};
  showModal(`<div class="result-view"><div class="result-emblem">${icon(win?'trophy':'shield')}</div><div class="modal-eyebrow">${win?'VICTORY · A NEW DAWN':battle.survival?'UNTIL THE LAST WARRIOR':'REGROUP AND RETURN'}</div><h2 id="modal-title">${win?'胜利属于你':battle.survival?'荣光长存':'重整旗鼓'}</h2><p class="modal-intro">${win?(battle.level===29?'王庭已经倒下。三十面旗帜，将见证这段征途。':victory[battle.config.goal]):battle.survival?`你的军团迎战了 ${battle.wave} 波，传奇将被铭记。`:battle.lossReason+'。'+battle.config.tip}</p>${win?`<div class="result-stars">${'★'.repeat(save.cleared[battle.level]||1)}${'☆'.repeat(3-(save.cleared[battle.level]||1))}</div>`:''}<div class="result-stats"><div><b>${clock(battle.time)}</b><span>战斗时间</span></div><div><b>${battle.stats.kills}</b><span>击败敌军</span></div><div><b>${fmt(battle.stats.goldMined)}</b><span>开采黄金</span></div></div><div class="result-reward">${reward?`获得 ${reward} 水晶 ◇ · 已自动保存`:'调整军团配置，再次挑战'}</div><div class="result-actions"><button class="secondary-button" data-action="campaign">战役地图</button>${win&&battle.level<LEVELS.length-1?`<button class="primary-button" data-new-level="${battle.level+1}">下一场战役 ${icon('arrow-right')}</button>`:`<button class="primary-button" data-action="restart">再次出征 ${icon('arrow-right')}</button>`}</div></div>`);
}
function train(type){sound.unlock();const result=battle.train(type);if(!result.ok)toast(result.message);else if(battle.status==='ready')toast(`${UNITS[type].name}已加入队列，开始战斗后进行训练`);updateUI();}
function skill(type){sound.unlock();const result=battle.skill(type);if(!result.ok)toast(result.message);updateUI();}
function command(order){if(['won','lost'].includes(battle.status))return;battle.command(order);sound.play('click');updateUI();}
function pause(){if(modalOpen)return;if(battle.status==='ready'){toast('点击「开始战斗」开启战役');return;}if(battle.status==='playing')battle.status='paused';else if(battle.status==='paused')battle.status='playing';updateUI();persist();}
function toggleSound(){sound.enabled=!sound.enabled;save.sound=sound.enabled;if(sound.enabled){sound.unlock();sound.play('trained');}persist();updateUI();}
async function action(name){
  sound.unlock();if(name==='supplies'){supplies();return;}
  if(name==='start'){battle.start();announce('秩序的旗帜已升起。先发展经济，再组织进攻。');updateUI();}
  else if(name==='campaign')campaign();else if(name==='armory')armory();else if(name==='codex')codex();else if(name==='settings')settings();else if(name==='help')help();else if(name==='close-modal')closeModal();else if(name==='pause')pause();else if(name==='speed'){speed=speed===1?2:speed===2?3:1;$('speed-button').textContent=speed+'×';}
  else if(name==='camera-home')renderer.setCamera(0);else if(name==='release'){battle.selected=null;updateUI();}else if(name==='sound')toggleSound();else if(name==='settings-sound'){toggleSound();settings();}else if(name==='reduced'){save.reduced=!save.reduced;renderer.reduced=save.reduced;persist();settings();}
  else if(name==='survival')showModal(modalHeader('HOLD THE LINE','守护最后的防线','每一次坚守，都是新的传奇。')+`<p class="modal-intro">开始无尽模式将替换当前战场，保留已有战役进度与升级。难度采用设置中的选项。</p><div class="result-actions"><button class="secondary-button" data-action="campaign">返回地图</button><button class="primary-button" data-action="start-survival">开始无尽防线 ${icon('arrow-right')}</button></div>`);
  else if(name==='start-survival')newBattle(0,true);else if(name==='restart')newBattle(battle.level,battle.survival);
  else if(name==='restart-confirm')showModal(modalHeader('A FRESH START','重新集结','本场战斗将从头开始，战役进度与永久升级会保留。')+`<div class="result-actions"><button class="secondary-button" data-action="settings">返回设置</button><button class="primary-button" data-action="restart">重新开始 ${icon('arrow-right')}</button></div>`);
  else if(name==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('此浏览器不支持全屏，可横屏获得更大视野');}catch{toast('此浏览器暂时无法进入全屏，可尝试横屏游戏');}}
}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.action)action(el.dataset.action);else if(el.dataset.unit)train(el.dataset.unit);else if(el.dataset.command)command(el.dataset.command);else if(el.dataset.skill)skill(el.dataset.skill);else if(el.dataset.campaignTab)campaign(el.dataset.campaignTab);else if(el.dataset.selectLevel!==undefined)levelBrief(Number(el.dataset.selectLevel));else if(el.dataset.newLevel!==undefined){const i=Number(el.dataset.newLevel);if(canPlay(save,i))newBattle(i);}else if(el.dataset.levelInfo!==undefined)campaign();else if(el.dataset.upgrade){const k=el.dataset.upgrade,l=save.upgrades[k]||0;if(l<3&&save.gems>=l+1){save.gems-=l+1;save.upgrades[k]=l+1;persist();armory();updateUI();sound.play('trained');toast('升级完成，将于下一场战斗生效');}}else if(el.dataset.cancelTraining!==undefined){battle.cancelTraining(Number(el.dataset.cancelTraining));queue();updateUI();}});
$('queue-indicator').addEventListener('click',queue);
document.addEventListener('change',e=>{if(e.target.id==='difficulty-select'){save.difficulty=e.target.value;persist();toast('难度将在下一场战斗生效');}});
$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal();});
const keys=new Set();
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){if(modalOpen)closeModal();else if(battle.selected){battle.selected=null;updateUI();}else pause();return;}
  if(modalOpen){if(e.key==='Tab'){const focusable=[...document.querySelector('.modal').querySelectorAll('button:not(:disabled),select,input,a')].filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===document.querySelector('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}
  if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;
  const k=e.key.toLowerCase();if([' ','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);
  if(k==='a')battle.manual.left=true;if(k==='d')battle.manual.right=true;if(k===' '&&battle.selected)battle.manual.attack=true;
  if(e.repeat)return;if('123456'.includes(k)&&k.length===1)train(unitTypes[Number(k)-1]);else if(k==='z')command('garrison');else if(k==='x')command('defend');else if(k==='c')command('attack');else if(k==='q')skill('rage');else if(k==='e')skill('heal');else if(k==='p')pause();else if(k===' '&&!battle.selected&&battle.status==='ready')action('start');
});
document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(k==='a')battle.manual.left=false;if(k==='d')battle.manual.right=false;if(k===' ')battle.manual.attack=false;});
window.addEventListener('blur',()=>{keys.clear();battle.manual={left:false,right:false,attack:false};});
let drag=null;
$('battlefield').addEventListener('pointerdown',e=>{if(modalOpen)return;sound.unlock();drag={x:e.clientX,y:e.clientY,camera:renderer.targetCamera,moved:false};$('battlefield').setPointerCapture(e.pointerId);});
$('battlefield').addEventListener('pointermove',e=>{if(!drag)return;const d=e.clientX-drag.x;if(Math.abs(d)>5)drag.moved=true;if(drag.moved)renderer.setCamera(drag.camera-d/renderer.scale,true);});
$('battlefield').addEventListener('pointerup',e=>{if(!drag)return;if(!drag.moved){const rect=$('battlefield').getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top;let best=null,dist=55;for(const u of battle.units.filter(u=>u.team===0)){const p=renderer.unitScreen(u),d=Math.hypot(p.x-x,p.y-35*renderer.scale-y);if(d<dist){best=u;dist=d;}}if(best){battle.selected=best.id;toast(`已控制${UNITS[best.type].name} · A/D 移动，空格攻击`);}else battle.selected=null;updateUI();}drag=null;});
$('battlefield').addEventListener('pointercancel',()=>drag=null);
$('battlefield').addEventListener('wheel',e=>{e.preventDefault();renderer.setCamera(renderer.targetCamera+(Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY));},{passive:false});
$('minimap').addEventListener('pointerdown',e=>{const r=$('minimap').getBoundingClientRect();renderer.setCamera((e.clientX-r.left)/r.width*WORLD-renderer.visibleWidth/2);});
$('minimap').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();renderer.setCamera(renderer.targetCamera+(e.key==='ArrowRight'?200:-200));}});
const observer=new ResizeObserver(()=>renderer.resize());observer.observe($('battle-viewport'));
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(battle.status==='playing'){battle.status='paused';wasPlaying=false;}keys.clear();battle.manual={left:false,right:false,attack:false};persist();updateUI();}});
window.addEventListener('pagehide',()=>persist());
function frame(now){const realDt=Math.min(.08,(now-lastTime)/1000);lastTime=now;if(!modalOpen){if(keys.has('arrowleft'))renderer.setCamera(renderer.targetCamera-realDt*650);if(keys.has('arrowright'))renderer.setCamera(renderer.targetCamera+realDt*650);if(battle.selected&&(battle.manual.left||battle.manual.right)){const u=battle.units.find(u=>u.id===battle.selected);if(u)renderer.setCamera(u.x-renderer.visibleWidth*.45);}}
  if(!modalOpen)for(let i=0;i<speed;i++)battle.update(realDt);
  const events=battle.events.splice(0);for(const ev of events){if(['train','trained','attack','wave','skill'].includes(ev.type))sound.play(ev.type);if(ev.type==='wave')announce(battle.survival?`第 ${ev.wave} 波敌军来袭 · 守住雕像！`:'敌军开始推进，准备迎战！');if(ev.type==='boss')announce(`敌方${UNITS[ev.unitType].name}统领加入战场！`);if(ev.type==='skill')announce(ev.skill==='rage'?'军团狂怒 · 全军伤害提升 60%':'治愈之光 · 全军恢复生命');if(ev.type==='end')endBattle(ev.win);}
  renderer.draw(battle,now);uiTime+=realDt;saveTime+=realDt;if(uiTime>.12){updateUI();uiTime=0;}if(saveTime>5){persist();saveTime=0;}requestAnimationFrame(frame);
}
renderStatic();updateUI();requestAnimationFrame(frame);
if(battle.status==='paused')toast('已恢复上次战斗，点击「继续战斗」接着玩');
if(!saveAvailable)toast('浏览器存储暂不可用，当前游戏仍可正常游玩');

if(migrated)toast("0.2.0 已保留旧版水晶、升级与通关星级。旧战斗已回到对应章节营地。");

document.addEventListener('click',e=>{
  const el=e.target.closest('button');if(!el||el.disabled)return;
  if(el.dataset.chapter!==undefined)campaign('campaign',Number(el.dataset.chapter));
  if(el.dataset.armoryTab)armory(el.dataset.armoryTab);
  if(el.dataset.wardrobeUnit){wardrobeUnit=el.dataset.wardrobeUnit;armory('skins');}
  if(el.dataset.buySkin){const id=el.dataset.buySkin;if(purchaseSkin(save,id)){equipSkin(save,wardrobeUnit,id);applyReadyLoadout();persist();armory('skins');toast('皮肤已解锁，并为所选兵种装备');}}
  if(el.dataset.equipSkin){if(equipSkin(save,wardrobeUnit,el.dataset.equipSkin)){applyReadyLoadout();persist();armory('skins');toast(battle.status==='ready'?'战甲已换装':'战甲将在下一场战斗生效');}}
  if(el.dataset.buyItem){if(purchaseItem(save,el.dataset.buyItem)){persist();armory('supplies');updateUI();sound.play('trained');}}
  if(el.dataset.useItem)useItem(el.dataset.useItem);
});
